import { useEffect } from 'preact/hooks';
import { FEATURES } from '../../config';
import { daysBetween, localDate } from '../../data/db';
import { useApp } from '../../data/store';
import { EXERCISES, KIND_LABEL, REGION_LABEL, type Exercise } from '../../rehab/exercises';
import { PHASE_LABEL, buildPlan, planTag } from '../../rehab/planner';
import { bioHistory, bioLine, daysBefore, repShare } from '../../rehab/bioHistory';
import type { Side } from '../../core';
import { STRETCH_VIDEO_ONLY, clipFlip, clipFor, clipUrl, isListed } from '../../rehab/demoClips';
import { planFor, programFor } from '../../rehab/motion';
import { RehabStill, holdTime } from '../rehab/stage';
import { AppBar, Notice } from '../components/common';
import { Icon } from '../icons';
import { LIVE_TASK_SHORT } from '../labels';

function ExerciseThumb({ ex, affectedSide }: { ex: Exercise; affectedSide: Side }) {
  // Stretches show their clip's hold frame while their 2D illustration is hidden (STRETCH_VIDEO_ONLY).
  const clip = STRETCH_VIDEO_ONLY && ex.kind === 'stretch' ? clipFor(ex.id, programFor(ex.id)?.steps[0]?.id) : undefined;
  if (clip) {
    const sx = clipFlip(clip, affectedSide, true) ? -1.3 : 1.3;
    return <img class="ex-thumb-clip" src={clipUrl(clip, 'hold.jpg')} alt="" loading="lazy" style={{ transform: `scale(${sx}, 1.3)` }} />;
  }
  const t = holdTime(planFor(ex));
  return (
    <RehabStill ex={ex} t={t} view={{ affectedSide, mirror: true, showMuscle: true, callouts: false, ghostHands: false, compact: true }} />
  );
}

const WEEKDAY = ['일', '월', '화', '수', '목', '금', '토'];

function ExerciseRow({
  ex,
  reason,
  done,
  side,
  tag,
  tagTone,
}: {
  ex: Exercise;
  reason?: string;
  done?: boolean;
  side: Side;
  /** Place in today's order (planTag, SRS-RHB-021). */
  tag?: string;
  tagTone?: string;
}) {
  return (
    <a class="list-item" href={`#/exercise/${ex.id}`}>
      <span class="ex-thumb" style={{ position: 'relative' }} aria-label={done ? '오늘 완료' : '미완료'}>
        <ExerciseThumb ex={ex} affectedSide={side} />
        {done && (
          <span class="thumb-done">
            <Icon name="check" />
          </span>
        )}
      </span>
      <div class="grow">
        {tag && <span class={`chip ${tagTone ?? ''}`}>{tag}</span>}
        <div style={{ fontWeight: 600 }}>{ex.title}</div>
        <div class="xsmall ink2">
          {KIND_LABEL[ex.kind]} · {ex.regions.map((r) => REGION_LABEL[r]).join('·')} ·{' '}
          {ex.reps ? `${ex.reps}회` : `${Math.round(ex.durationSec / 60)}분`}
        </div>
        {reason && <div class="xsmall muted">{reason}</div>}
      </div>
      <Icon name="chev" class="chev" />
    </a>
  );
}

/** `showAll`: open with the full exercise list unfolded and in view (#/rehab/all, the intro page's link). */
export function Rehab({ showAll = false }: { showAll?: boolean }) {
  const { profile, sessions, rehab, synk } = useApp();
  const lastSynk = synk[synk.length - 1];
  useEffect(() => {
    if (showAll) document.getElementById('all-exercises')?.scrollIntoView({ block: 'start' });
  }, [showAll]);
  if (!profile) return null;
  const latest = [...sessions].reverse().find((s) => s.analysis.scores);
  const plan = buildPlan({
    daysSinceOnset: daysBetween(profile.onsetDate),
    latest: FEATURES.rehab === 'personalized' ? (latest?.analysis ?? null) : null,
  });
  const today = localDate();
  const doneToday = new Set(rehab.filter((r) => r.date === today).map((r) => r.exerciseId));
  const week = Array.from({ length: 7 }, (_, k) => {
    const d = new Date();
    d.setDate(d.getDate() - (6 - k));
    const ymd = localDate(d);
    return { label: WEEKDAY[d.getDay()]!, count: new Set(rehab.filter((r) => r.date === ymd).map((r) => r.exerciseId)).size };
  });
  const activeDays = week.filter((w) => w.count > 0).length;
  // The live guide's week against the week before (SRS-RHB-018).
  const bioWeek = bioHistory(rehab, daysBefore(today, 6), today);
  const bioPrev = bioHistory(rehab, daysBefore(today, 13), daysBefore(today, 7));

  return (
    <>
      <AppBar title="재활 가이드" sub={`${PHASE_LABEL[plan.phase]} · 하루 ${plan.sessionsPerDay}회 권장`} />
      <main class="main">
        <div class="card accent tight">
          <h3>{PHASE_LABEL[plan.phase]} 맞춤 계획</h3>
          <p class="small ink2">{plan.phaseReason}</p>
          {plan.priorities.length > 0 ? (
            <p class="small" style={{ margin: '4px 0' }}>
              <b>오늘 순서</b> {plan.priorities.map((p) => `${REGION_LABEL[p.region]} ${p.pct}%`).join(' → ')}
              {plan.items.some((i) => i.role === 'safety') && plan.priorities[0]?.region === 'eye' ? ' (눈이 다 감기지 않아 눈 먼저)' : ''}
            </p>
          ) : (
            plan.phase !== 'synkinesis' && (
              <p class="small" style={{ margin: '4px 0' }}>
                평가 전이라 기본 순서(눈 → 입 → 이마)입니다. 평가하면 약한 부위부터 바뀝니다.
              </p>
            )
          )}
          <p class="xsmall muted">
            {latest && FEATURES.rehab === 'personalized'
              ? plan.phase === 'synkinesis'
                ? '힘 빼기로 시작해, 더 심하게 측정된 동반운동부터 준비 마사지 → 스트레칭·분리 운동 순서로 놓았습니다.'
                : '최근 평가에서 약한 부위부터, 부위마다 준비 마사지 → 그 부위 운동 순서로 놓았습니다(%는 건강한 쪽 대비).'
              : '평가를 하면 약한 부위에 맞춰 계획이 조정됩니다.'}{' '}
            계획 규칙 {plan.version}
          </p>
        </div>

        {plan.notices.map((n) => (
          <div class="card warn tight">
            <Notice tone="warn">
              <span class="small">{n}</span>
            </Notice>
          </div>
        ))}

        {plan.items.length > 0 && (
          <a
            class="btn primary block"
            href={`#/routine/${Math.max(
              0,
              plan.items.findIndex((i) => !doneToday.has(i.exercise.id)),
            )}`}
          >
            <Icon name="play" /> {plan.items.every((i) => doneToday.has(i.exercise.id)) ? '오늘 루틴 다시 하기' : '오늘 루틴 이어서 하기'} ·{' '}
            {plan.items.length}가지 · 약 {Math.round(plan.items.reduce((t, i) => t + planFor(i.exercise).total + 10, 0) / 60)}분
          </a>
        )}
        {plan.phase !== 'acute' && lastSynk && (
          <a class="card tight" href={`#/synk/${lastSynk.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>
            <div class="row between">
              <div>
                <b>연합운동 결과</b>
                <div class="xsmall ink2">
                  {lastSynk.result.findings.length ? `함께 움직이는 곳 ${lastSynk.result.findings.length}군데` : '뚜렷한 연합운동 없음'} ·
                  곳마다 맞는 운동을 추천합니다.
                </div>
              </div>
              <Icon name="chev" />
            </div>
          </a>
        )}
        <div class="section-title">오늘의 운동</div>
        <div class="card tight">
          <div class="list">
            {plan.items.map((i) => (
              <ExerciseRow
                ex={i.exercise}
                reason={i.reason}
                done={doneToday.has(i.exercise.id)}
                side={profile.affectedSide}
                tag={planTag(i, plan.phase)}
                tagTone={i.role === 'safety' ? 'warn' : i.role === 'core' && i.rank === 1 ? 'accent' : ''}
              />
            ))}
          </div>
        </div>

        <div class="section-title">최근 7일 · {activeDays}일 운동함</div>
        <div class="card tight">
          <div class="dots7" role="list">
            {week.map((w) => (
              <div role="listitem" aria-label={`${w.label}요일 ${w.count}가지`}>
                <div class={`d ${w.count > 0 ? 'on' : ''}`}>{w.count || ''}</div>
                {w.label}
              </div>
            ))}
          </div>
          <p class="xsmall muted">숫자는 그날 완료한 운동 가짓수입니다.</p>
        </div>

        {bioWeek.length > 0 && (
          <>
            <div class="section-title">실시간 안내로 한 운동 · 최근 7일</div>
            <div class="card tight">
              <ul class="small" style={{ margin: 0, paddingLeft: '18px' }}>
                {bioWeek.map((s) => {
                  const now = repShare(s);
                  const prev = bioPrev.find((p) => p.task === s.task);
                  const before = prev ? repShare(prev) : null;
                  return (
                    <li>
                      <b>{LIVE_TASK_SHORT[s.task]}</b> {bioLine(s)}
                      {now !== null && before !== null && (
                        <span class="ink2">
                          {' '}
                          (지난주 {Math.round(before * 100)}% → {Math.round(now * 100)}%)
                        </span>
                      )}
                    </li>
                  );
                })}
              </ul>
              <p class="xsmall muted">
                목표 유지 = 노란 목표에 닿아 1초 버틴 시도. 건강한 쪽 힘 과다·다른 곳 같이 움직임이 줄어드는 것도 좋아지는 신호입니다. ‘운동
                중 마비 쪽 %’는 일부러 작게 움직일 때의 값이라 평가 결과와 다릅니다.
              </p>
            </div>
          </>
        )}

        <details class="card tight" id="all-exercises" open={showAll}>
          <summary class="ink2" style={{ fontWeight: 600 }}>
            전체 운동 목록 ({EXERCISES.filter(isListed).length})
          </summary>
          <div class="list">
            {EXERCISES.filter(isListed).map((e) => (
              <ExerciseRow ex={e} done={doneToday.has(e.id)} side={profile.affectedSide} />
            ))}
          </div>
        </details>
        <details class="card tight evidence">
          <summary class="ink2" style={{ fontWeight: 600 }}>
            왜 이 운동인가요? 근거 보기
          </summary>
          <ul class="small">
            <li>
              <b>신경근 재교육</b> — Manikandan, <i>Clinical Rehabilitation</i> 2007: 벨마비 환자 59명 무작위 대조 연구에서 환자에게 맞춘
              신경근 재교육 운동이 전기자극 위주의 일반 치료보다 3개월 뒤 얼굴 회복이 좋았습니다.
            </li>
            <li>
              <b>조기 물리치료</b> — Nicastri 등, <i>Neurorehabilitation and Neural Repair</i> 2013: 중증 벨마비(HB 5·6등급)에서 초기부터
              물리치료를 함께 한 군의 회복 정도와 속도가 더 좋았습니다.
            </li>
            <li>
              <b>스트레칭과 구조화 운동</b> — Santiago 등, <i>Scientific Reports</i> 2024: 급성 벨마비에서 스트레칭과 마비 쪽 운동을 함께
              하는 프로그램을 보고했습니다.
            </li>
            <li>
              <b>동반운동 관리</b> — 동반운동이 생긴 뒤에는 근력 강화보다 이완·스트레칭·분리 운동을 권하는 것이 일반적인 재활 원칙입니다.
            </li>
            <li>
              <b>선택적 스트레칭 동작</b> — 한림대학교 동탄성심병원 도수치료실 「안면마비 선택적 스트레칭」 영상을 바탕으로 재구성했습니다.
            </li>
          </ul>
          <p class="xsmall muted">
            안면 운동의 효과에 대한 근거는 아직 연구마다 차이가 있고 수준이 높지 않습니다. 이 앱은 치료를 대신하지 않으며, 계획은 담당
            의료진과 상의하세요.
          </p>
        </details>
        <p class="xsmall muted center">운동 내용은 일반적인 안면 재활 원칙에 따른 정보이며, 개인 치료 계획은 담당 의료진과 상의하세요.</p>
      </main>
    </>
  );
}
